begin;
select set_config('request.jwt.claim.sub','7a65cdab-a9c3-412d-b5d8-7d1bcd857c1d',true);
select set_config('request.jwt.claims','{"sub":"7a65cdab-a9c3-412d-b5d8-7d1bcd857c1d","role":"authenticated"}',true);
do $$ begin if not exists(select 1 from public.schoolpro_schools where id='d342eb87-8d6a-477a-a380-7fab83f586b7' and owner_id='7a65cdab-a9c3-412d-b5d8-7d1bcd857c1d' and name='IHLINK ACADEMY (Testing)') then raise exception 'Expected testing school not found; refusing to seed';end if;end $$;

insert into public.schoolpro_result_term_settings(school_id,session,term,term_start_date,term_end_date,next_term_begins,class_days,principal_name,form_master_remark_template,principal_remark_template,updated_by)
values('d342eb87-8d6a-477a-a380-7fab83f586b7','2025/2026','First Term','2025-09-15','2025-12-05','2026-01-12',60,'Grace Adebayo','Keep practising and participate confidently.','Continue working steadily towards your learning goals.','7a65cdab-a9c3-412d-b5d8-7d1bcd857c1d')on conflict(school_id,session,term)do nothing;
with groups as(select * from jsonb_to_recordset('[{"g": 1, "name": "Nursery 1", "arm": "A", "level": "nursery", "code": "N1-A"}, {"g": 2, "name": "Nursery 1", "arm": "B", "level": "nursery", "code": "N1-B"}, {"g": 3, "name": "Nursery 2", "arm": "A", "level": "nursery", "code": "N2-A"}, {"g": 4, "name": "Nursery 2", "arm": "B", "level": "nursery", "code": "N2-B"}, {"g": 5, "name": "Nursery 3", "arm": "A", "level": "nursery", "code": "N3-A"}, {"g": 6, "name": "Nursery 3", "arm": "B", "level": "nursery", "code": "N3-B"}, {"g": 7, "name": "Basic 1", "arm": "A", "level": "primary", "code": "B1-A"}, {"g": 8, "name": "Basic 1", "arm": "B", "level": "primary", "code": "B1-B"}, {"g": 9, "name": "Basic 2", "arm": "A", "level": "primary", "code": "B2-A"}, {"g": 10, "name": "Basic 2", "arm": "B", "level": "primary", "code": "B2-B"}, {"g": 11, "name": "Basic 3", "arm": "A", "level": "primary", "code": "B3-A"}, {"g": 12, "name": "Basic 3", "arm": "B", "level": "primary", "code": "B3-B"}, {"g": 13, "name": "Basic 4", "arm": "A", "level": "primary", "code": "B4-A"}, {"g": 14, "name": "Basic 4", "arm": "B", "level": "primary", "code": "B4-B"}, {"g": 15, "name": "Basic 5", "arm": "A", "level": "primary", "code": "B5-A"}, {"g": 16, "name": "Basic 5", "arm": "B", "level": "primary", "code": "B5-B"}, {"g": 17, "name": "JSS 1", "arm": "A", "level": "junior_secondary", "code": "J1-A"}, {"g": 18, "name": "JSS 1", "arm": "B", "level": "junior_secondary", "code": "J1-B"}, {"g": 19, "name": "JSS 2", "arm": "A", "level": "junior_secondary", "code": "J2-A"}, {"g": 20, "name": "JSS 2", "arm": "B", "level": "junior_secondary", "code": "J2-B"}, {"g": 21, "name": "JSS 3", "arm": "A", "level": "junior_secondary", "code": "J3-A"}, {"g": 22, "name": "JSS 3", "arm": "B", "level": "junior_secondary", "code": "J3-B"}, {"g": 23, "name": "SS 1", "arm": "A", "level": "senior_secondary", "code": "S1-A"}, {"g": 24, "name": "SS 1", "arm": "B", "level": "senior_secondary", "code": "S1-B"}, {"g": 25, "name": "SS 2", "arm": "A", "level": "senior_secondary", "code": "S2-A"}, {"g": 26, "name": "SS 2", "arm": "B", "level": "senior_secondary", "code": "S2-B"}, {"g": 27, "name": "SS 3", "arm": "A", "level": "senior_secondary", "code": "S3-A"}, {"g": 28, "name": "SS 3", "arm": "B", "level": "senior_secondary", "code": "S3-B"}]'::jsonb) as c(g int,name text,arm text,level text,code text)),marks as(
 select g,n,k,level,mod(n*11+k*7+g*3+1*5,66)+30 total from groups cross join generate_series(1,40)n cross join generate_series(1,10)k),components as(
 select *,greatest(3,least(10,floor(total*.1)::int))a1,greatest(3,least(10,floor(total*.1)::int))a2,greatest(3,least(10,floor(total*.1)::int))t1,greatest(3,least(10,floor(total*.1)::int))t2 from marks)
insert into public.schoolpro_results(id,school_id,student_id,subject_id,term,session,assessment_scheme_id,assessment_scores,teacher_comment,head_teacher_comment)
select md5('ihlink-academy-test-v1:result:'||g||':'||n||':'||k||':1')::uuid,'d342eb87-8d6a-477a-a380-7fab83f586b7',md5('ihlink-academy-test-v1:student:'||g||':'||n)::uuid,md5('ihlink-academy-test-v1:subject:'||g||':'||k)::uuid,'First Term','2025/2026',
 (select id from public.schoolpro_assessment_schemes where school_id='d342eb87-8d6a-477a-a380-7fab83f586b7' and school_level=level order by is_default desc,created_at limit 1),
 jsonb_build_object('assignment_1',a1,'assignment_2',a2,'test_1',t1,'test_2',t2,'exam',total-a1-a2-t1-t2),
 case when total>=80 then 'Excellent understanding; keep challenging yourself.' when total>=65 then 'Good progress. Practise the areas discussed in class.' when total>=50 then 'Steady effort; more revision will improve confidence.' else 'Needs guided practice and regular revision.' end,
 case when total>=70 then 'A promising performance. Keep up the effort.' else 'Continue learning steadily with support and practice.' end
 from components on conflict(student_id,subject_id,term,session)do nothing;
-- Run the same review and publication functions used by SchoolPro, with owner authorization.
do $$ declare r record;begin for r in select id from public.schoolpro_results where school_id='d342eb87-8d6a-477a-a380-7fab83f586b7' and session='2025/2026' and term='First Term' and status='draft' and student_id in(select id from public.schoolpro_students where school_id='d342eb87-8d6a-477a-a380-7fab83f586b7' and admission_number like 'IH-TST-2026-%') loop perform public.review_schoolpro_result(r.id,'approved','Synthetic Academy testing dataset; not a real pupil assessment');end loop;end $$;
select public.publish_schoolpro_selected_results('d342eb87-8d6a-477a-a380-7fab83f586b7','First Term','2025/2026',array(select id from public.schoolpro_students where school_id='d342eb87-8d6a-477a-a380-7fab83f586b7' and admission_number like 'IH-TST-2026-%'),false);
insert into public.schoolpro_result_domain_ratings(school_id,student_id,term,session,definition_id,rating,rating_label,rated_by)
select 'd342eb87-8d6a-477a-a380-7fab83f586b7',s.id,'First Term','2025/2026',d.id,2+mod((right(s.admission_number,3)::int)+d.position+1,4),substr('ABCD',1+mod((right(s.admission_number,3)::int)+d.position+1,4),1),'7a65cdab-a9c3-412d-b5d8-7d1bcd857c1d' from public.schoolpro_students s cross join public.schoolpro_result_domain_definitions d where s.school_id='d342eb87-8d6a-477a-a380-7fab83f586b7' and s.admission_number like 'IH-TST-2026-%' and d.school_id=s.school_id and d.is_active on conflict(student_id,term,session,definition_id)do nothing;
commit;
select 'First Term sample results published' as result;
